/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('audit')` (or `ctx.tryUse` for an optional dependency). */
export interface AuditPublicApi {
  /** Append one entry. Call it inside the same transaction as the change (outbox once introduced), so a change is never saved without its history. Roles are resolved through access.rolesOf when the actor is staff and actorRoles is omitted. Used by: identity, access, settings, media, notifications, customers, sellers, catalog, offers, inventory, purchasing, warehouse, orders, payments, shipping, returns, finance, promotions, advertising, reviews, messaging, support, trust, content, workqueues, reports, wallet. */
  record(entry: RecordInput): Promise<string>;
  /** Bulk actions (bulk catalog edit, payout run items) in one call Used by: catalog, offers, inventory, finance. */
  recordMany(entries: RecordInput[]): Promise<string[]>;
  /** Staff history for a record, embedded in other modules' admin detail responses (order, seller, payout) Used by: orders, sellers, finance, returns, customers, catalog, settings. */
  historyOf(targetType: string, targetId: string, limit?: number): Promise<AuditEntry[]>;
  /** Batched, paged history per record for the Action history card on admin 360 views (order, seller, customer, payout run). includeRelated also matches entries where the record is one of relatedTargets. Newest first. Used by: graphql. */
  trailOf(targetType: string, targetIds: string[], opts: { includeRelated?: boolean, category?: string, page?: common.PageInput }): Promise<Map<string, common.Page<AuditEntry>>>;
  /** The action history with filters, newest first (same as GET /entries) Used by: graphql. */
  searchEntries(filters: AuditFilters, page: common.PageInput): Promise<common.Page<AuditEntry>>;
  /** One entry with before/after and approval Used by: graphql. */
  getEntry(entryId: string): Promise<AuditEntry | null>;
  /** Export rows for reports dataset audit.admin.entries (filters are AuditFilters; values are already redacted at record time) Used by: reports. */
  exportRows(dataset: string, filters: unknown, principal: identity.Principal, cursor?: string): Promise<{ rows: unknown[], nextCursor?: string }>;
}

/* ------------------------------------------------------------------ tables (Kysely row types) */

/** Tables in the `audit` schema. Use with `ctx.db` (already scoped to the schema). */
export interface AuditDb {
  /** Append-only (no UPDATE/DELETE grants for the app role; triggers refuse UPDATE, DELETE, TRUNCATE and dropping a partition outside a purge). Partitioned by range on at, one partition per market month (audit_partitions.entries_<entry_partitions.name>), so the key is (id, at) and seq is unique per (seq, at) (identity: unique in practice). hash = sha256(prev_hash || canonical row). */
  entries: {
    id: string;
    seq: Generated<number>;
    at: Date;
    actor_kind: string;
    actor_id: string | null;
    actor_name: string | null;
    actor_roles: Json;
    action: string;
    action_label: string;
    module: string;
    category: string;
    target_type: string;
    target_id: string;
    target_ref: string | null;
    target_label: string | null;
    target_screen: string | null;
    seller_id: string | null;
    reason: string | null;
    before: Json | null;
    after: Json | null;
    before_text: string | null;
    after_text: string | null;
    evidence: Json;
    approval_request_id: string | null;
    approval_note: string | null;
    request_id: string | null;
    ip: string | null;
    visible_to_seller: boolean;
    /** generated: refs, labels, reason, names */
    search: string | null;
    prev_hash: Uint8Array;
    hash: Uint8Array;
  };
  /** Related targets for history lookups (an order item entry also appears under its order and seller). Partitioned like entries (at is the entry's at, so a target row lives in the same month as its entry and its partition is dropped with the entry's); written in the same transaction as the entry, without a foreign key so dropping a month needs no reference check. */
  entry_targets: {
    /** entries.id */
    entry_id: string;
    target_type: string;
    target_id: string;
    at: Date;
  };
  /** The month partitions of entries and entry_targets ([from_at, to_at), one market month; the first month after the partitioning migration may be shorter where it meets the UTC months of older rows). Created ahead by audit.prepare-partitions and on demand by record; dropped by audit.purge-expired. */
  entry_partitions: {
    /** lower bound in UTC as YYYYMMDD_HH24MI: tables audit_partitions.entries_<name> and entry_targets_<name> */
    name: string;
    from_at: Date;
    to_at: Date;
    created_at: Date;
  };
  /** Projection of access approval requests referenced by entries; updated from access events, so entries stay immutable */
  approval_states: {
    approval_request_id: string;
    state: string;
    approvers: Json;
    steps: Json;
    awaiting: string | null;
    decided_at: Date | null;
    updated_at: Date;
  };
  /** Single row */
  retention: {
    id: number;
    retain_years: number;
    pending_years: number | null;
    pending_reason: string | null;
    pending_approval_request_id: string | null;
    pending_requested_by: string | null;
    updated_by: string | null;
    updated_at: Date | null;
    last_purge_at: Date | null;
    last_purge_removed: number | null;
    last_purge_through: Date | null;
  };
  /** Signed chain checkpoints: written after each successful verification and before a purge, so verification continues across purged ranges and a rewritten chain is detected even if every hash was recomputed */
  checkpoints: {
    id: string;
    seq: number;
    hash: Uint8Array;
    /** hex HMAC-SHA256 of seq || hash */
    mac: string;
    /** secret derivation label, e.g. audit.checkpoint.v1 */
    key_id: string;
    kind: 'verified' | 'purge';
    created_at: Date;
  };
  integrity_checks: {
    id: string;
    started_at: Date;
    finished_at: Date | null;
    from_seq: number;
    to_seq: number;
    ok: boolean | null;
    broken_at_seq: number | null;
  };
}

/* ------------------------------------------------------------------ endpoints */

export const endpoints = defineEndpoints({
  listEntries: {
    area: "admin",
    method: "GET",
    path: "/entries",
    auth: "staff",
    permission: "audit.entries.view",
    scope: "staff",
    summary: "Action history with filters",
    desc: "Newest first. Each item is complete (actor and role, action, target, reason, before → after, approval state), so the table and phone list render from one call.",
    query: () =>
      z.object({
        q: z.string().optional(),
        actorId: z.string().optional(),
        roleKey: z.string().optional(),
        module: z.string().optional(),
        category: z.enum(["financial", "seller_enforcement", "catalog", "orders", "returns", "customers", "settings", "access", "security", "content", "advertising", "support", "trust", "inventory", "shipping", "other"]).optional(),
        targetType: z.string().optional(),
        targetId: z.string().optional(),
        sellerId: z.uuid().optional(),
        action: z.string().optional(),
        approvalState: z.enum(["not_required", "pending", "partially_approved", "approved", "rejected", "returned", "cancelled", "expired"]).optional(),
        from: z.iso.datetime({ offset: true }).optional(),
        to: z.iso.datetime({ offset: true }).optional(),
      }),
    paging: true,
    response: () => AuditEntry,
    status: 200,
    screens: ["admin/audit"],
    phase: 1,
  },
  getEntry: {
    area: "admin",
    method: "GET",
    path: "/entries/{id}",
    auth: "staff",
    permission: "audit.entries.view",
    scope: "staff",
    summary: "One entry with evidence and approval history",
    params: () =>
      z.object({
        id: z.uuid(),
      }),
    response: () => AuditEntry,
    status: 200,
    screens: ["admin/audit"],
    phase: 1,
  },
  getSummary: {
    area: "admin",
    method: "GET",
    path: "/summary",
    auth: "staff",
    permission: "audit.entries.view",
    scope: "staff",
    summary: "Counts for the filter chips (pending second review, financial, enforcement, settings)",
    query: () =>
      z.object({
        from: z.iso.date().optional(),
        to: z.iso.date().optional(),
      }),
    response: () => AuditSummary,
    status: 200,
    screens: ["admin/audit","admin/dashboard"],
    phase: 1,
  },
  listTargetHistory: {
    area: "admin",
    method: "GET",
    path: "/targets/{type}/{id}",
    auth: "staff",
    permission: "audit.entries.view",
    scope: "staff",
    summary: "History of one record (order, seller, payout, product, setting…)",
    desc: "Includes entries where the record is a related target. Used for 'staff history with reasons' panels.",
    params: () =>
      z.object({
        type: z.string(),
        id: z.string(),
      }),
    paging: true,
    response: () => AuditEntry,
    status: 200,
    screens: ["admin/order","admin/seller","admin/payouts","admin/customers","admin/settings","admin/staff"],
    phase: 1,
  },
  createExport: {
    area: "admin",
    method: "POST",
    path: "/exports",
    auth: "staff",
    permission: "audit.entries.export",
    scope: "staff",
    summary: "Export filtered history (authorized, recorded)",
    desc: "Records the reason in the action history, then creates an authorized export job through reports.requestExport (dataset audit.admin.entries, csv or jsonl). Poll GET /exports/{id} for the download link. Limited to reports.maxExportRows, read through settings (settings.get('reports.maxExportRows')) and checked against the matching entry count before the job is created.",
    body: () => z.object({
      get filters() {
        return AuditFilters;
      },
      format: z.enum(["csv", "jsonl"]),
      reason: z.string(),
    }),
    response: () => reports.ExportJob,
    status: 202,
    errors: ["EXPORT_TOO_LARGE"],
    audited: true,
    screens: ["admin/audit"],
    phase: 1,
  },
  listExports: {
    area: "admin",
    method: "GET",
    path: "/exports",
    auth: "staff",
    permission: "audit.entries.export",
    scope: "staff",
    summary: "My exports (all exports with audit.retention.manage)",
    desc: "Proxies reports.listExports for dataset audit.admin.entries: the caller's own jobs, or every requester's with audit.retention.manage.",
    query: () =>
      z.object({
        status: z.enum(["queued", "running", "ready", "failed", "expired"]).optional(),
      }),
    paging: true,
    response: () => reports.ExportJob,
    status: 200,
    screens: ["admin/audit"],
    phase: 1,
  },
  getExport: {
    area: "admin",
    method: "GET",
    path: "/exports/{id}",
    auth: "staff",
    permission: "audit.entries.export",
    scope: "staff",
    summary: "Export status and a fresh download link",
    desc: "Proxies reports.getExport: only the requester may download, and each signed link is recorded.",
    params: () =>
      z.object({
        id: z.uuid(),
      }),
    response: () => reports.ExportJob,
    status: 200,
    errors: ["NOT_FOUND"],
    audited: true,
    screens: ["admin/audit"],
    phase: 1,
  },
  getRetention: {
    area: "admin",
    method: "GET",
    path: "/retention",
    auth: "staff",
    permission: "audit.entries.view",
    scope: "staff",
    summary: "Retention setting and last purge",
    response: () => RetentionPolicy,
    status: 200,
    screens: ["admin/audit","admin/settings"],
    phase: 1,
  },
  updateRetention: {
    area: "admin",
    method: "PUT",
    path: "/retention",
    auth: "staff",
    permission: "audit.retention.manage",
    scope: "staff",
    summary: "Change how long history is kept",
    desc: "Lengthening applies now. Shortening is saved as pendingChange and sent to the Business Owner (approval action audit.retention.change): the normal 200 with pendingChange.approval (FORMAT.md, Approval responses); it applies when approved and is dropped when rejected, cancelled or expired. When access answers allowed for the caller, it applies at once. APPROVAL_REQUIRED (409, nothing saved) only while the access module is disabled, so no approval can be requested; FORBIDDEN when the caller may not even propose it. While a shortening waits, no other retention change is accepted (ILLEGAL_TRANSITION).",
    body: () => z.object({
      retainYears: z.number().int(),
      reason: z.string(),
    }),
    response: () => RetentionPolicy,
    status: 200,
    errors: ["BELOW_LEGAL_MINIMUM","APPROVAL_REQUIRED","ILLEGAL_TRANSITION"],
    audited: true,
    approval: "Approval action audit.retention.change. Shortening retention needs Business Owner approval",
    events: ["audit.retention.changed"],
    screens: ["admin/audit","admin/settings"],
    phase: 1,
  },
  getIntegrity: {
    area: "admin",
    method: "GET",
    path: "/integrity",
    auth: "staff",
    permission: "audit.entries.view",
    scope: "staff",
    summary: "Hash-chain check result",
    response: () => IntegrityStatus,
    status: 200,
    screens: ["admin/audit"],
    phase: 1,
  },
  listOwnSellerEntries: {
    area: "seller",
    method: "GET",
    path: "/entries",
    auth: "seller",
    permission: "audit.own-history.view",
    scope: "own-seller",
    summary: "Changes made on this seller account",
    desc: "Seller member changes (staff, permissions, store details, payout destination) and staff actions marked visible to the seller. Staff names are not shown.",
    query: () =>
      z.object({
        from: z.iso.date().optional(),
        to: z.iso.date().optional(),
        targetType: z.string().optional(),
      }),
    paging: true,
    response: () => SellerAuditEntry,
    status: 200,
    screens: ["seller/staff","seller/store"],
    phase: 1,
  },
});

